from typing import List, Optional

from taf.rfrl.csv4all.resources.test_cases import NetactFeatureTest
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, function_wrapper
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class NetactLiveUpdateTest(NetactFeatureTest):

    def __init__(self, nodes_details, test_nodes_details: List[dict], iterations_per_node: int,
                 netact_dict: dict, report: bool, calculate_kpi: Optional[bool] = False,
                 kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 use_testpackage: Optional[bool] = False, restore_to_target_sw: Optional[bool] = False,
                 feature: Optional[str] = None, rollback: Optional[bool] = True, fallback: Optional[bool] = False,
                 stop_test_after_fail: bool = False, deintegrate_after_test: bool = True,
                 integrate_before_test: bool = True, config_type: str = None,
                 artifactory_location: str = "espoo2", package_suffix: str = "A54",
                 l3_call_method: Optional[callable] = None, synchronize_software_on_passive: bool = False,
                 yaft_path: str = "/home/ute", virtualenv_dir: str = None, rollback_reverse_order: bool = False,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0, cm_provision: bool = True,
                 diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, netact_dict, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, use_external_storage, download_path,
                         use_testpackage, restore_to_target_sw, feature, rollback, fallback, stop_test_after_fail,
                         deintegrate_after_test, integrate_before_test, config_type,
                         artifactory_location, package_suffix, l3_call_method, synchronize_software_on_passive,
                         yaft_path, virtualenv_dir, rollback_reverse_order, detailed_console_log,
                         collect_passed_logs, cm_provision, diagnostic_check)
        self.reset_incrementation = False

    @method_decorator()
    def live_update_precheck(self, node):
        if not node.check_if_live_update():
            raise FatalError("Live Update not performed, please check if paths are correct")
        if self.synchronize_software_on_passive:
            node.synchronize_software_on_passive()
        else:
            if self.iterations_per_node > 1:
                test_logger("Synchronize software on passive is False, loops cant be done. "
                            "Iterations number will be set to 1", "WARN")

    def test_setup(self):
        super().test_setup()
        self.check_for_passive_sw_before_test()

    @method_decorator()
    def verify_active_sw_after_fallback(self, node):
        software = node.source_sw if self.synchronize_software_on_passive else node.passive_sw_before_test
        node.verify_active_sw_version(software)

    @function_wrapper
    def check_for_passive_sw_before_test(self):
        if not self.synchronize_software_on_passive and self.perform_fallback:
            for node in self.test_nodes:
                node.passive_sw_before_test = node.get_passive_sw()
                if not node.passive_sw_before_test:
                    raise FatalError("Fallback cannot be done because passive sw is empty")
